Theorem A_rsa_complete_spec : forall AL, asan_img_ok AL -> rsa_complete_stmtA asegs AL A_RSA_COMPLETE.
Proof.
  intros AL IMG. unfold rsa_complete_stmtA, A_RSA_COMPLETE. intros until lo.
  intros RA_ SGN SGE PN PE ST LO0 SLO SPA MI RA ALWF CSOK AB OC ON OE SCS DC DN DE ->. unfold RSA_CTX_SIZE in OC, DC.
  pose proof (cs_ok_sb _ _ CSOK) as SB64. pose proof ALWF as ALWF'; unfold al_wf in ALWF'. pose proof IMG as IMG'; unfold asan_img_ok in IMG'.
  pose proof (bv_unsigned_in_range 64 sp) as SPB. change (bv_modulus 64) with (2^64) in SPB.
  ddestruct RA_ as (HD & HT & AN & AE & [NSN _] & [NSE _] & LEN & ALL & CAL & C0 & CB & _).
  pose proof CB as CB'; unfold RSA_CTX_SIZE in CB'.
  assert (MN : mpd_at asegs m LB (r_N r)) by (split; [exact (Forall_inv ALL)| lia]).
  assert (ME : mpd_at asegs m LB (r_E r)) by (split; [exact (Forall_inv (Forall_inv_tail ALL))| lia]).
  pose proof (Forall_inv_tail (Forall_inv_tail ALL)) as ZS. clear ALL.
  unfold rsa_zero_mpds, rsa_zero_offs in ZS. cbn [map] in ZS.
  (* [comment removed for export] *)
  assert (ZP : rw_cells asegs m (C + 64) (mpi_cells 0 (Z_to_bv 64 0) 0 (Z_to_bv 64 0))) by (refine (proj1 (proj1 (Forall_forall _ _) ZS (mpd_z (C + 64)) _)); cbn [In]; tauto).
  assert (ZQ : rw_cells asegs m (C + 80) (mpi_cells 0 (Z_to_bv 64 0) 0 (Z_to_bv 64 0))) by (refine (proj1 (proj1 (Forall_forall _ _) ZS (mpd_z (C + 80)) _)); cbn [In]; tauto).
  assert (ZD : rw_cells asegs m (C + 48) (mpi_cells 0 (Z_to_bv 64 0) 0 (Z_to_bv 64 0))) by (refine (proj1 (proj1 (Forall_forall _ _) ZS (mpd_z (C + 48)) _)); cbn [In]; tauto).
  assert (ZDP : rw_cells asegs m (C + 96) (mpi_cells 0 (Z_to_bv 64 0) 0 (Z_to_bv 64 0))) by (refine (proj1 (proj1 (Forall_forall _ _) ZS (mpd_z (C + 96)) _)); cbn [In]; tauto).
  assert (ZDQ : rw_cells asegs m (C + 112) (mpi_cells 0 (Z_to_bv 64 0) 0 (Z_to_bv 64 0))) by (refine (proj1 (proj1 (Forall_forall _ _) ZS (mpd_z (C + 112)) _)); cbn [In]; tauto).
  assert (ZQP : rw_cells asegs m (C + 128) (mpi_cells 0 (Z_to_bv 64 0) 0 (Z_to_bv 64 0))) by (refine (proj1 (proj1 (Forall_forall _ _) ZS (mpd_z (C + 128)) _)); cbn [In]; tauto).
  clear ZS.
  dpose MN as [[_ (_ & _ & LENN & NRN & OWNN)] _]. dpose ME as [[_ (_ & _ & LENE & NRE & OWNE)] _]. unfold MPI_MAX_LIMBS in NRN, NRE.
  assert (DN' : 1 <= md_n (r_N r) -> md_p (r_N r) + 4 * md_n (r_N r) <= lo \/ bv_unsigned sp <= md_p (r_N r)).
  { intros Hn. destruct (md_own (r_N r)) eqn:EO; [destruct OWNN as [P0 N0]; exfalso; clear - N0 Hn; lia| exact (DN eq_refl)| exfalso; exact (NSN eq_refl)]. }
  assert (DE' : 1 <= md_n (r_E r) -> md_p (r_E r) + 4 * md_n (r_E r) <= lo \/ bv_unsigned sp <= md_p (r_E r)).
  { intros Hn. destruct (md_own (r_E r)) eqn:EO; [destruct OWNE as [P0 N0]; exfalso; clear - N0 Hn; lia| exact (DE eq_refl)| exfalso; exact (NSE eq_refl)]. }
  assert (TRN' : forall ma mb, mpd_at asegs ma LB (r_N r) -> munch [(lo, bv_unsigned sp)] ma mb -> wmono asegs ma mb -> mpd_at asegs mb LB (r_N r)).
  { intros ma mb H MUx WMx. eapply mpd_at_munch; [exact H| exact NSN| exact MUx| exact WMx| cbn; split; [rewrite AN; lia| exact I]|].
    intros EO. cbn. split; [| exact I]. destruct (DN EO); lia. }
  assert (TRE' : forall ma mb, mpd_at asegs ma LB (r_E r) -> munch [(lo, bv_unsigned sp)] ma mb -> wmono asegs ma mb -> mpd_at asegs mb LB (r_E r)).
  { intros ma mb H MUx WMx. eapply mpd_at_munch; [exact H| exact NSE| exact MUx| exact WMx| cbn; split; [rewrite AE; lia| exact I]|].
    intros EO. cbn. split; [| exact I]. destruct (DE EO); lia. }
  assert (SCSF : crange CS lo (bv_unsigned sp + -192 - lo)) by (eapply crange_sub; [exact SCS| clear; lia| clear - SLO; lia]).
  pose proof (sgn01 _ (mpd_val_sg1 _ SGN)) as RN01. pose proof (sgn01 _ (mpd_val_sg1 _ SGE)) as RE01.
  (* [comment removed for export] *)
  assert (ON16 : aobj asegs AL CS m (md_addr (r_N r)) 16) by (rewrite AN; eapply aobj_sub; [exact OC| lia| lia]).
  assert (OE16 : aobj asegs AL CS m (md_addr (r_E r)) 16) by (rewrite AE; eapply aobj_sub; [exact OC| lia| lia]).
  assert (OP16 : aobj asegs AL CS m (C + 64) 16) by (eapply aobj_sub; [exact OC| lia| lia]).
  assert (OQ16 : aobj asegs AL CS m (C + 80) 16) by (eapply aobj_sub; [exact OC| lia| lia]).
  assert (OD16 : aobj asegs AL CS m (C + 48) 16) by (eapply aobj_sub; [exact OC| lia| lia]).
  assert (ODP16 : aobj asegs AL CS m (C + 96) 16) by (eapply aobj_sub; [exact OC| lia| lia]).
  assert (ODQ16 : aobj asegs AL CS m (C + 112) 16) by (eapply aobj_sub; [exact OC| lia| lia]).
  assert (OQP16 : aobj asegs AL CS m (C + 128) 16) by (eapply aobj_sub; [exact OC| lia| lia]).
  assert (OC48 : aobj asegs AL CS m C 48) by (eapply aobj_sub; [exact OC| lia| lia]).
  clear OWNN OWNE.
  unfold rsa_head_cells in HD. unfold rsa_tail_cells in HT.
  Ltac cur_aobj CSOK SCS MU ON ON1 :=
    lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mx _) =>
      lazymatch type of ON with (?P -> aobj ?segs ?AL ?CS ?m0 ?A ?n) =>
        assert (ON1 : P -> aobj segs AL CS mx A n)
          by (let Hn := fresh in intros Hn; eapply (aobj_munch segs AL CS CSOK _ m0 mx); [| exact MU| exact (ON Hn)];
              unfold w_client; apply Forall_cons; [cbn [fst snd]; eapply crange_sub; [exact SCS| clear; lia| clear; lia] | apply Forall_nil])
      end end.
  Ltac qside SLO SPA SPB LO0 C0 DC OX TR MX AX DX NRX SCSF :=
    first [ exact OX
          | match goal with MUx : munch _ ?m0 ?mc, WMx : wmono asegs ?m0 ?mc |- mpd_at _ ?mc _ _ => eapply TR; [exact MX| exact MUx| exact WMx] end
          | rewrite AX; reflexivity
          | exact SCSF
          | lazymatch goal with |- ?x = Z_to_bv 64 ?v => is_evar v; symmetry; exact (Z_to_bv_bv_unsigned x) end
          | clear - SLO SPA SPB LO0 C0 DC AX DX NRX; first [lia | rewrite AX; lia | intros Hn; destruct (DX Hn); lia]
          | match goal with |- ?g => idtac "QSIDE-LEFT:" g end ].
  pose proof (munch_refl [(lo, bv_unsigned sp)] m) as MU. pose proof (wmono_refl asegs m) as WM.
  carve_frame 192%nat ST.
  (* [comment removed for export] *)
  do 14 zstep.
  (* [comment removed for export] *)
  pose proof (abase_got _ _ _ AB) as GOT. pose proof (abase_gsb _ _ _ AB) as GSB. rewrite (proj1 IMG') in GOT.
  zstep. zstep. zstep. clear GOT GSB. zstep.
  (* [comment removed for export] *)
  zstep. zstep. zstep. zstep. zstep.
  all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "PROLOGUE-LEFT:" g end.
  pose proof (A_mpi_cmp_int_spec AL IMG) as SPc. unfold mpi_cmp_int_stmtA in SPc.
  (* [comment removed for export] *)
  cur_aobj CSOK SCS MU ON ONa.
  callxA_sp (bv_unsigned sp + -192)
    (eapply SPc with (lo := lo) (LB := LB) (dX := r_N r) (z := 0); rewrite ?(unsigned_lit (bv_unsigned sp + -192)) by lia;
